            _context.SaveChanges();

            var person = _context.People.First(p => p.LastName == "Test");
            Assert.IsType<Student>(person);
            Assert.Equal("Test, Inherit", person.FullName);
        }

        [Fact]
        public void Instructor_InheritsFromPerson()
