            var person = _context.People.First(p => p.LastName == "Person");
            Assert.IsType<Instructor>(person);
            Assert.Equal("Person, Prof", person.FullName);
        }

        [Fact]
        public void Course_DepartmentRelationship_Works()
        {
            var dept = new Department { Name = "Related", Budget = 100, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 8001, Title = "Related Course", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var retrieved = _context.Courses.Include(c => c.Department).First(c => c.CourseID == 8001);
            Assert.NotNull(retrieved.Department);
            Assert.Equal("Related", retrieved.Department.Name);
        }

        public void Dispose()
        {
            _context.Database.EnsureDeleted();
            _context.Dispose();
        }
    }
}

