namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests : IDisposable
    {
        private readonly SchoolContext _context;

        public SchoolContextTests()
        {
            _context = TestDbContextFactory.Create();
        }

        [Fact]
        public void CanAddAndRetrieveStudent()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };

            _context.Students.Add(student);
            _context.SaveChanges();

            var retrieved = _context.Students.First(s => s.LastName == "Student");
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal(new DateTime(2023, 1, 1), retrieved.EnrollmentDate);
        }

        [Fact]
        public void CanAddAndRetrieveInstructor()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Prof",
                LastName = "Teacher",
                HireDate = new DateTime(2000, 1, 1),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };

            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var retrieved = _context.Instructors.First(i => i.LastName == "Teacher");
            Assert.Equal("Prof", retrieved.FirstMidName);
            Assert.Equal(new DateTime(2000, 1, 1), retrieved.HireDate);
        }

        [Fact]
        public void CanAddAndRetrieveCourse()
        {
            var dept = new Department { Name = "Test", Budget = 1000, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 5001, Title = "Test Course", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var retrieved = _context.Courses.First(c => c.CourseID == 5001);
            Assert.Equal("Test Course", retrieved.Title);
            Assert.Equal(3, retrieved.Credits);
        }

        [Fact]
        public void CanAddAndRetrieveDepartment()
        {
            var dept = new Department { Name = "Physics", Budget = 250000, StartDate = new DateTime(2015, 1, 1) };

            _context.Departments.Add(dept);
            _context.SaveChanges();

            var retrieved = _context.Departments.First(d => d.Name == "Physics");
            Assert.Equal(250000, retrieved.Budget);
            Assert.Equal(new DateTime(2015, 1, 1), retrieved.StartDate);
        }

        [Fact]
        public void CanAddAndRetrieveEnrollment()
        {
            var student = new Student { FirstMidName = "E", LastName = "Enrolled", EnrollmentDate = DateTime.Now };
            _context.Students.Add(student);
            var dept = new Department { Name = "D", Budget = 100, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 6001, Title = "Enrolled Course", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var enrollment = new Enrollment { StudentID = student.ID, CourseID = course.CourseID, Grade = Grade.A };
            _context.Enrollments.Add(enrollment);
            _context.SaveChanges();

            var retrieved = _context.Enrollments.First(e => e.StudentID == student.ID);
            Assert.Equal(Grade.A, retrieved.Grade);
            Assert.Equal(course.CourseID, retrieved.CourseID);
        }

        [Fact]
        public void CanAddAndRetrieveOfficeAssignment()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Office",
                LastName = "Holder",
                HireDate = DateTime.Now,
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var office = new OfficeAssignment { InstructorID = instructor.ID, Location = "Building A Room 100" };
            _context.OfficeAssignments.Add(office);
            _context.SaveChanges();

            var retrieved = _context.OfficeAssignments.First(o => o.InstructorID == instructor.ID);
            Assert.Equal("Building A Room 100", retrieved.Location);
        }

        [Fact]
        public void CanAddAndRetrieveCourseAssignment()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Assign",
                LastName = "Test",
                HireDate = DateTime.Now,
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            var dept = new Department { Name = "CA", Budget = 100, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 7001, Title = "Assigned", Credits = 2, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var assignment = new CourseAssignment { InstructorID = instructor.ID, CourseID = course.CourseID };
            _context.CourseAssignments.Add(assignment);
            _context.SaveChanges();

            var retrieved = _context.CourseAssignments.First(ca => ca.InstructorID == instructor.ID && ca.CourseID == course.CourseID);
            Assert.Equal(instructor.ID, retrieved.InstructorID);
            Assert.Equal(course.CourseID, retrieved.CourseID);
        }

        [Fact]
        public void CanAddAndRetrieveNotification()
        {
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test notification",
                CreatedAt = DateTime.Now,
                CreatedBy = "TestUser",
                IsRead = false
            };

            _context.Notifications.Add(notification);
            _context.SaveChanges();

            var retrieved = _context.Notifications.First();
            Assert.Equal("Student", retrieved.EntityType);
            Assert.Equal("1", retrieved.EntityId);
            Assert.Equal("CREATE", retrieved.Operation);
            Assert.Equal("Test notification", retrieved.Message);
            Assert.False(retrieved.IsRead);
        }

        [Fact]
        public void Student_InheritsFromPerson()
        {
            var student = new Student { FirstMidName = "Inherit", LastName = "Test", EnrollmentDate = DateTime.Now };
            _context.Students.Add(student);
            _context.SaveChanges();

            var person = _context.People.First(p => p.LastName == "Test");
            Assert.IsType<Student>(person);
            Assert.Equal("Test, Inherit", person.FullName);
        }

        [Fact]
        public void Instructor_InheritsFromPerson()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Prof",
                LastName = "Person",
                HireDate = DateTime.Now,
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var person = _context.People.First(p => p.LastName == "Person");
            Assert.IsType<Instructor>(person);
            Assert.Equal("Person, Prof", person.FullName);
        }

        [Fact]
        public void Course_DepartmentRelationship_Works()
        {
            var dept = new Department { Name = "Related", Budget = 100, StartDate = DateTime.Now };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 8001, Title = "Related Course", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var retrieved = _context.Courses.Include(c => c.Department).First(c => c.CourseID == 8001);
            Assert.NotNull(retrieved.Department);
            Assert.Equal("Related", retrieved.Department.Name);
        }

        public void Dispose()
        {
            _context.Database.EnsureDeleted();
            _context.Dispose();
        }
    }
}

